#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left, *right;
} TreeNode;

static TreeNode* newNode(int v) {
    TreeNode* n = (TreeNode*)malloc(sizeof(TreeNode));
    n->val = v; n->left = NULL; n->right = NULL;
    return n;
}

static TreeNode* buildTree(const char* line) {
    const char* p = strchr(line, '[');
    if (!p) return NULL;
    p = strchr(p + 1, '[');
    if (!p) return NULL;
    ++p;

    int vals[30000], present[30000], n = 0;
    char token[64];
    while (*p && *p != ']') {
        while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n' || *p == ',') ++p;
        if (*p == ']') break;
        int k = 0;
        while (*p && *p != ',' && *p != ']') {
            if (k < (int)sizeof(token)-1) token[k++] = *p;
            ++p;
        }
        token[k] = '\0';
        if (strcmp(token, "null") == 0) present[n] = 0;
        else { present[n] = 1; vals[n] = atoi(token); }
        ++n;
    }
    if (n == 0 || !present[0]) return NULL;

    TreeNode* nodes[10000];
    TreeNode* root = newNode(vals[0]);
    nodes[0] = root;
    TreeNode* queue[10000];
    int head = 0, tail = 0;
    queue[tail++] = root;
    int i = 1;
    while (head < tail && i < n) {
        TreeNode* cur = queue[head++];
        if (i < n && present[i]) {
            cur->left = newNode(vals[i]);
            queue[tail++] = cur->left;
        }
        ++i;
        if (i < n && present[i]) {
            cur->right = newNode(vals[i]);
            queue[tail++] = cur->right;
        }
        ++i;
    }
    return root;
}

static void push(TreeNode*** st, int* top, int* cap, TreeNode* node) {
    if (*top >= *cap) {
        *cap *= 2;
        *st = (TreeNode**)realloc(*st, (*cap) * sizeof(TreeNode*));
    }
    (*st)[(*top)++] = node;
}

static int* findMode(TreeNode* root, int* returnSize) {
    *returnSize = 0;
    if (!root) return NULL;

    int cap = 128, top = 0;
    TreeNode** st = (TreeNode**)malloc(cap * sizeof(TreeNode*));
    TreeNode* cur = root;
    int hasPrev = 0, prev = 0, count = 0, maxCount = 0;

    while (top || cur) {
        while (cur) {
            push(&st, &top, &cap, cur);
            cur = cur->left;
        }
        cur = st[--top];
        if (hasPrev && cur->val == prev) ++count;
        else { prev = cur->val; count = 1; hasPrev = 1; }
        if (count > maxCount) maxCount = count;
        cur = cur->right;
    }

    int* result = (int*)malloc(10000 * sizeof(int));
    top = 0; cur = root; hasPrev = 0; count = 0;
    while (top || cur) {
        while (cur) {
            push(&st, &top, &cap, cur);
            cur = cur->left;
        }
        cur = st[--top];
        if (hasPrev && cur->val == prev) ++count;
        else { prev = cur->val; count = 1; hasPrev = 1; }
        if (count == maxCount) result[(*returnSize)++] = cur->val;
        cur = cur->right;
    }
    free(st);
    return result;
}

int main(void) {
    char line[200000];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    TreeNode* root = buildTree(line);
    int size = 0;
    int* result = findMode(root, &size);
    printf("[");
    for (int i = 0; i < size; ++i) {
        if (i) printf(",");
        printf("%d", result[i]);
    }
    printf("]\n");
    free(result);
    return 0;
}

