static vector<string> splitTokens(const string& line) {
    size_t first = line.find('[');
    size_t second = line.find('[', first + 1);
    size_t last = line.rfind(']');
    size_t innerLast = line.rfind(']', last - 1);
    string inner = line.substr(second + 1, innerLast - second - 1);

    vector<string> tokens;
    if (inner.find_first_not_of(" \t\r\n") == string::npos) return tokens;
    string token;
    stringstream ss(inner);
    while (getline(ss, token, ',')) {
        size_t a = token.find_first_not_of(" \t\r\n");
        size_t b = token.find_last_not_of(" \t\r\n");
        tokens.push_back(token.substr(a, b - a + 1));
    }
    return tokens;
}

static TreeNode* buildTree(const vector<string>& t) {
    if (t.empty() || t[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(t[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < t.size()) {
        TreeNode* node = q.front(); q.pop();
        if (t[i] != "null") {
            node->left = new TreeNode(stoi(t[i]));
            q.push(node->left);
        }
        ++i;
        if (i < t.size()) {
            if (t[i] != "null") {
                node->right = new TreeNode(stoi(t[i]));
                q.push(node->right);
            }
            ++i;
        }
    }
    return root;
}

int main() {
    string line;
    getline(cin, line);
    TreeNode* root = buildTree(splitTokens(line));
    vector<int> result = Solution().findMode(root);
    cout << "[";
    for (size_t i = 0; i < result.size(); ++i) {
        if (i) cout << ",";
        cout << result[i];
    }
    cout << "]\n";
}

