import java.io.*;
import java.util.*;

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

class Solution {
    public int[] findMode(TreeNode root) {
        if (root == null) return new int[0];

        ArrayDeque<TreeNode> stack = new ArrayDeque<>();
        ArrayList<Integer> result = new ArrayList<>();
        TreeNode cur = root;
        Integer previous = null;
        int count = 0, maxCount = 0;

        while (cur != null || !stack.isEmpty()) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.left;
            }
            cur = stack.pop();

            if (previous != null && cur.val == previous) count++;
            else {
                previous = cur.val;
                count = 1;
            }

            if (count > maxCount) {
                maxCount = count;
                result.clear();
                result.add(cur.val);
            } else if (count == maxCount) {
                result.add(cur.val);
            }

            cur = cur.right;
        }

        int[] answer = new int[result.size()];
        for (int i = 0; i < result.size(); i++) answer[i] = result.get(i);
        return answer;
    }
}

public class Main {
    static List<String> parseTreeTokens(String line) {
        int second = line.indexOf('[', line.indexOf('[') + 1);
        int last = line.lastIndexOf(']');
        int innerLast = line.lastIndexOf(']', last - 1);
        String inner = line.substring(second + 1, innerLast);
        List<String> tokens = new ArrayList<>();
        if (inner.trim().isEmpty()) return tokens;
        for (String s : inner.split(",")) tokens.add(s.trim());
        return tokens;
    }

    static TreeNode buildTree(List<String> tokens) {
        if (tokens.isEmpty() || tokens.get(0).equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tokens.get(0)));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.size()) {
            TreeNode node = q.remove();
            String left = tokens.get(i++);
            if (!left.equals("null")) {
                node.left = new TreeNode(Integer.parseInt(left));
                q.add(node.left);
            }
            if (i < tokens.size()) {
                String right = tokens.get(i++);
                if (!right.equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(right));
                    q.add(node.right);
                }
            }
        }
        return root;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        TreeNode root = buildTree(parseTreeTokens(br.readLine()));
        int[] result = new Solution().findMode(root);
        System.out.print("[");
        for (int i = 0; i < result.length; i++) {
            if (i > 0) System.out.print(",");
            System.out.print(result[i]);
        }
        System.out.println("]");
    }
}

